  const fullTotal = invoiceTotals(makeIssuedInvoice()).total;
  const paid = makePaidInvoice('C-003', '2024-01-25', fullTotal);

  const invoices = [draft.value, issued, paid];
  const result = vatSummary(invoices);

  // Only issued and paid should be included (draft excluded), both have qty 2 DES-HOUR
  assert.equal(result.value.length, 1);
  // Base should be from 2 invoices (issued + paid), each with qty 2 DES-HOUR with 5% discount
  // Each: 2 * 8500 * 0.95 = 16150, total = 32300
  assert.equal(result.value[0].base, 32300);
