  const invoice2 = makeIssuedInvoice('C-002', '2024-01-20');

  const invoices = [invoice1, invoice2];
  const result = vatSummary(invoices);

  // Both invoices have DES-HOUR qty 2 with 5% discount (from issueInvoice)
  // Each has base = 2 * 8500 * 0.95 = 16150
  // Each has vat = Math.round(16150 * 0.21) = 3392
  // Total: base = 32300, vat = 6784
  assert.equal(result.value.length, 1);
  assert.equal(result.value[0].rate, 21);
  assert.equal(result.value[0].base, 32300);
  assert.equal(result.value[0].vat, 6784);
});

